        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "L'asino va picchiato, perché non può picchiare lui; e s'ei potesse picchiare, ci pesterebbe sotto i piedi e ci strapperebbe la carne a morsi.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Solo rimaneva solenne e immutabile, il paesaggio, colle lunghe linee orientali, dai toni caldi e robusti. Sfinge misteriosa, che rappresentava i fantasmi passeggieri, con un carattere di necessità fatale.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Tu hai bisogno di vivere alla grand'aria, come me, e per noi altri infermi di mente e di nervi la grand'aria è la vita di una grande città, le continue emozioni, il movimento, le lotte con sé e con gli altri, se vuoi pur così.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Vi siete mai trovata, dopo una pioggia di autunno, a sbaragliare un esercito di formiche, tracciando sbadatamente il nome del vostro ultimo ballerino sulla sabbia del viale?", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Chi pratica con zoppi all'anno zoppica.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Ciascuno deve pensare alla sua barba prima di pensare a quella degli altri.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Così dicendo si fregava le mani e rideva, ma colle labbra e non col cuore.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Fa il mestiere che sai, che se non arricchisci camperai.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Fra suocera e nuora ci si sta in malora.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Il buon pilota si prova alle burrasche.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Il cammino fatale, incessante, spesso faticoso e febbrile che segue l'umanità per raggiungere la conquista del progresso, è grandioso nel suo risultato, visto nell'insieme, da lontano.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Solo l'osservatore, travolto anch'esso dalla fiumana, guardandosi attorno, ha il diritto di interessarsi ai deboli che restano per via, ai fiacchi che si lasciano sorpassare dall'onda per finire più presto, ai vinti che levano le braccia disperate, e piegano il capo sotto il piede brutale dei sopravvegnenti.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Il mare non ha paese nemmen lui, ed è di tutti quelli che lo stanno ad ascoltare, di qua e di là dove nasce e muore il sole.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Il matrimonio è come una trappola di topi; quelli che son dentro vorrebbero uscire, e gli altri ci girano intorno per entrarvi.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "La Madonna ci ha fatto il miracolo, perché il Signore ci è stato troppe volte in questa casa!", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Maritati e muli vogliono star soli.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Né visita di morto senza riso, né sposalizio senza pianto.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Ogni buco ha il suo chiodo, chi l'ha vecchio e chi l'ha nuovo!", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Per me io voglio morire dove son nato [...] Ringrazia Dio piuttosto, che t'ha fatto nascer qui; e guardati dall'andare a morire lontano dai sassi che ti conoscono.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Una mela fradicia guasta tutte le altre.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Uomo povero ha i giorni lunghi.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Ciascuno fa il suo interesse... Al giorno d'oggi l'interesse va prima della parentela...", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Gli affari vostri fanno a pugni con gli affari degli altri, che diavolo!... Apposta bisogna tirarli dalla vostra... Fra di loro si danno la mano... son tutti parenti... Voi siete l'estraneo... siete il nemico, che diavolo!", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Nei piccoli paesi c'è della gente che farebbe delle miglia per venire a portarvi la cattiva nuova.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "E anche lui, adesso che la roba passava per le sue mani, comprendeva finalmente i dispiaceri che aveva dato alla povera donna; se ne pentiva, cercava di farseli perdonare, colla pazienza, colle cure amorevoli standole sempre intorno.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Fra tutte quelle piccine, in tutte le famiglie, succedeva lo stesso diavoleto che mastro-don Gesualdo aveva fatto nascere nei grandi e nel paese.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Ah! La mia roba? Voglio vederli! Dopo quarant'anni che ci ho messo a farla... un tarì dopo l'altro!... Piuttosto cavatemi fuori il fegato e tutto il resto in una volta, chè li ho fradici dai dispiaceri...", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Il mondo andava ancora pel suo verso, mentre non c'era più speranza per lui, roso dal baco al pari di una mela fradicia che deve cascare dal ramo.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Volevano morir piuttosto di una schioppettata, o d'altra morte che manda Dio. Ma il colèra, no, non lo volevano!", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Era alta, magra, aveva soltanto un seno fermo e vigoroso da bruna – e pure non era più giovane – era pallida come se avesse sempre addosso la malaria, e su quel pallore due occhi grandi così, e delle labbra fresche e rosse, che vi mangiavano.", Author = "Giovanni Verga" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giovanni_Verga", Text = "Malpelo si chiamava così perché aveva i capelli rossi; ed aveva i capelli rossi perché era un ragazzo malizioso e cattivo, che prometteva di riuscire un fior di birbone.", Author = "Giovanni Verga" },
